import useFocusHelper from "./useFocusHelper.js";
import { h } from "vue";

//#region src/composables/useButton.ts
function useButton() {
	function renderButton({ focusable, focusType }, data, slotData) {
		const isFocusable = focusable && focusType.includes("date");
		return h("button", {
			...data,
			tabindex: isFocusable ? 0 : -1
		}, [slotData, isFocusable && useFocusHelper()]);
	}
	return { renderButton };
}

//#endregion
export { useButton as default };