import { getResolvedCalendarSystem, isGregorianCalendar, toCalendarTimestamp } from "../utils/calendarSystem.js";
import { addToDate, copyTimestamp, getCalendarEndOfMonth, getCalendarStartOfMonth, getEndOfMonth, moveRelativeDays, nextCalendarDay, nextDay, parseCalendarTimestamp, prevCalendarDay, prevDay, today, updateDayOfYear, updateFormatted, updateRelative, updateWeekday } from "@timestamp-js/core";

//#region src/composables/useMove.ts
const useMoveEmits = ["moved"];
function useMove(props, { parsedView, parsedValue, direction, maxDays, times, emittedValue, emit }) {
	function withDay(timestamp, day) {
		return copyTimestamp({
			...timestamp,
			day
		});
	}
	function isAllowedWeekday(timestamp) {
		return props.weekdays.length === 0 || props.weekdays.includes(Number(timestamp.weekday));
	}
	function moveToAllowedWeekday(timestamp, forward) {
		const calendar = getCalendarSystem();
		let moved = timestamp;
		for (let i = 0; i < 7 && !isAllowedWeekday(moved); i += 1) moved = addToDate(moved, { day: forward ? 1 : -1 }, calendar);
		return moved;
	}
	function getCalendarSystem() {
		return getResolvedCalendarSystem(props.calendarSystem);
	}
	function moveCalendarToAllowedWeekday(timestamp, forward) {
		const calendar = getCalendarSystem();
		let moved = timestamp;
		for (let i = 0; i < 7 && !isAllowedWeekday(moved); i += 1) moved = forward ? nextCalendarDay(moved, calendar) : prevCalendarDay(moved, calendar);
		return moved;
	}
	/**
	* Moves the calendar the desired amount. This is based on the 'view'.
	* A month calendar moves by prev/next month
	* A week calendar moves by prev/next week
	* Other considerations are the allowed weekdays; if a day of the week should be displayed (e.g., weekends turned off).
	* @param {number} amount The amount to move (default 1)
	* @fires 'moved' with current Timestamp
	*/
	function move(amount = 1) {
		const calendar = getCalendarSystem();
		if (amount === 0) {
			let moved = parseCalendarTimestamp(today(calendar), calendar);
			moved = updateWeekday(moved, calendar);
			moved = updateFormatted(moved, calendar);
			moved = updateDayOfYear(moved, calendar);
			moved = updateRelative(moved, times.now, false, calendar);
			emittedValue.value = moved.date;
			emit("moved", moved);
			return;
		}
		let moved = copyTimestamp(parsedValue.value);
		const lastDayOfMonth = getEndOfMonth(moved, calendar);
		const forward = amount > 0;
		const mover = forward ? nextDay : prevDay;
		const limit = forward ? lastDayOfMonth.day : 1;
		let count = forward ? amount : -amount;
		direction.value = forward ? "next" : "prev";
		const dayCount = props.weekdays.length;
		while (--count >= 0) switch (parsedView.value) {
			case "month":
				if (isGregorianCalendar(props.calendarSystem) !== true) {
					const calendarMoved = toCalendarTimestamp(moved, calendar);
					const boundary = forward === true ? getCalendarEndOfMonth(calendarMoved, calendar) : getCalendarStartOfMonth(calendarMoved, calendar);
					let nextCalendarValue = forward === true ? nextCalendarDay(boundary, calendar) : prevCalendarDay(boundary, calendar);
					nextCalendarValue = moveCalendarToAllowedWeekday(nextCalendarValue, forward);
					moved = nextCalendarValue;
					break;
				}
				moved = withDay(moved, limit);
				moved = mover(moved, calendar);
				moved = updateWeekday(moved, calendar);
				moved = moveToAllowedWeekday(moved, forward);
				break;
			case "week":
			case "week-agenda":
			case "week-scheduler":
				moved = moveRelativeDays(moved, mover, dayCount, props.weekdays, calendar);
				break;
			case "day":
			case "scheduler":
			case "agenda":
				moved = moveRelativeDays(moved, mover, maxDays.value, props.weekdays, calendar);
				break;
			case "month-interval":
			case "month-agenda":
			case "month-scheduler":
				moved = withDay(moved, limit);
				moved = mover(moved, calendar);
				break;
			case "resource": moved = moveRelativeDays(moved, mover, maxDays.value, props.weekdays, calendar);
		}
		moved = updateWeekday(moved, calendar);
		moved = updateFormatted(moved, calendar);
		moved = updateDayOfYear(moved, calendar);
		moved = updateRelative(moved, times.now, false, calendar);
		emittedValue.value = moved.date;
		emit("moved", moved);
	}
	return { move };
}

//#endregion
export { useMove as default, useMoveEmits };