import { getCalendarScopeData } from "../utils/calendarSystem.js";

//#region src/composables/useCheckChange.ts
const useCheckChangeEmits = ["change"];
function useCheckChange(emit, { days, lastStart, lastEnd, calendarSystem }) {
	function checkChange() {
		const dayList = days.value;
		if (dayList.length === 0) return false;
		const start = dayList[0].date;
		const end = dayList[dayList.length - 1].date;
		if (!lastStart.value || !lastEnd.value || start !== lastStart.value || end !== lastEnd.value) {
			lastStart.value = start;
			lastEnd.value = end;
			const calendar = calendarSystem();
			const calendarDays = dayList.map((day) => getCalendarScopeData(day, calendar).calendarTimestamp);
			emit("change", {
				start,
				end,
				days: dayList,
				calendarStart: calendarDays[0].date,
				calendarEnd: calendarDays[calendarDays.length - 1].date,
				calendarDays,
				calendarSystem: calendar
			});
			return true;
		}
		return false;
	}
	return { checkChange };
}

//#endregion
export { useCheckChange as default, useCheckChangeEmits };