import { computed, reactive, watch } from "vue";
import { copyTimestamp, parseCalendarTimestamp, parseDate, parseTimestamp, validateTimestamp } from "@timestamp-js/core";

//#region src/composables/useTimes.ts
/**
* export of useTimesProps
*/
const useTimesProps = { 
/**
* Current timestamp override used for deterministic current-time rendering.
*
* @category behavior
*/
now: {
	type: String,
	validator: (v) => v === "" || validateTimestamp(v),
	default: ""
} };
/**
* Reactive timestamps & computed properties for time tracking
*/
function useTimes(props) {
	/**
	* 'times' is a reactive object containing 'now' and 'today'
	*/
	const times = reactive({
		now: parseTimestamp("0000-00-00 00:00"),
		today: parseTimestamp("0000-00-00")
	});
	/**
	* Parsed current timestamp
	*/
	const parsedNow = computed(() => props.now ? parseCalendarTimestamp(props.now, props.calendarSystem) : getNow());
	/**
	* Watch for changes in parsedNow
	*/
	watch(parsedNow, () => updateCurrent(), { flush: "sync" });
	/**
	* Sets 'times.now' (relative) to 'times.today' (relative)
	*/
	function setCurrent() {
		if (times.now && times.today) {
			times.now = copyTimestamp({
				...times.now,
				current: true,
				past: false,
				future: false
			});
			times.today = copyTimestamp({
				...times.today,
				current: true,
				past: false,
				future: false
			});
		}
	}
	/**
	* Updates current timestamps
	*/
	function updateCurrent() {
		const now = parsedNow.value || getNow();
		times.now = updateTime(now, updateDay(now, times.now));
		times.today = updateDay(now, times.today);
	}
	/**
	* Get the current date as a Timestamp
	*/
	function getNow() {
		return parseDate(/* @__PURE__ */ new Date(), props.calendarSystem);
	}
	/**
	* Update date info of target timestamp
	*/
	function updateDay(now, target) {
		if (now.date !== target.date) return copyTimestamp({
			...target,
			year: now.year,
			month: now.month,
			day: now.day,
			calendarId: now.calendarId,
			weekday: now.weekday,
			date: now.date
		});
		return target;
	}
	/**
	* Update time info of target timestamp
	*/
	function updateTime(now, target) {
		if (now.time !== target.time) return copyTimestamp({
			...target,
			hour: now.hour,
			minute: now.minute,
			second: now.second,
			millisecond: now.millisecond,
			time: now.time
		});
		return target;
	}
	return {
		times,
		parsedNow,
		setCurrent,
		updateCurrent,
		getNow,
		updateDay,
		updateTime
	};
}

//#endregion
export { useTimes as default, useTimesProps };