import { resolveCssLength } from "../utils/helpers.js";
import { toCalendarTimestamp } from "../utils/calendarSystem.js";
import { computed, watch } from "vue";
import { createCalendarDayList, getCalendarEndOfMonth, getCalendarEndOfWeek, getCalendarMonthFormatter, getCalendarStartOfMonth, getCalendarStartOfWeek, isOutsideCalendarMonth, validateNumber } from "@timestamp-js/core";

//#region src/composables/useMonth.ts
const useMonthProps = {
	/**
	* Height in pixels or CSS units for each month day cell.
	*
	* @category layout
	*/
	dayHeight: {
		type: [Number, String],
		default: 0,
		validator: (v) => validateNumber(v)
	},
	/**
	* Minimum height in pixels or CSS units for each month day cell.
	*
	* @category layout
	*/
	dayMinHeight: {
		type: [Number, String],
		default: 0,
		validator: (v) => validateNumber(v)
	},
	/**
	* Function that returns inline styles for month day cells.
	*
	* @category style
	*/
	dayStyle: Function,
	/**
	* Function that returns CSS classes for month day cells.
	*
	* @category style
	*/
	dayClass: Function,
	/**
	* Function that returns inline styles for weekday header cells.
	*
	* @category style
	*/
	weekdayStyle: Function,
	/**
	* Function that returns CSS classes for weekday header cells.
	*
	* @category style
	*/
	weekdayClass: Function,
	/**
	* Padding applied inside month day cells.
	*
	* @category layout
	*/
	dayPadding: String,
	/**
	* Minimum number of weeks rendered by the month display.
	*
	* @category layout
	*/
	minWeeks: {
		type: [Number, String],
		default: 1,
		validator: (v) => validateNumber(v)
	},
	/**
	* Uses shortened month labels.
	*
	* @category display
	*/
	shortMonthLabel: Boolean,
	/**
	* Shows ISO work week labels.
	*
	* @category display
	*/
	showWorkWeeks: Boolean,
	/**
	* Shows the month label.
	*
	* @category display
	*/
	showMonthLabel: {
		type: Boolean,
		default: true
	},
	/**
	* Shows the day-of-year label for each day.
	*
	* @category display
	*/
	showDayOfYearLabel: Boolean,
	/**
	* Enables rendering days outside the active month.
	*
	* @category display
	*/
	enableOutsideDays: Boolean,
	/**
	* Hides days outside the active month.
	*
	* @category display
	*/
	noOutsideDays: Boolean,
	/**
	* Enables hover behavior tracking for month day cells.
	*
	* @category behavior
	*/
	hover: Boolean,
	/**
	* Forces mini mode or lets mini mode follow the configured breakpoint.
	*
	* @category layout
	*/
	miniMode: {
		type: [Boolean, String],
		validator: (v) => [
			true,
			false,
			"auto"
		].includes(v)
	},
	/**
	* Breakpoint used when `mini-mode` is set to `auto`.
	*
	* @category layout
	*/
	breakpoint: {
		type: [Number, String],
		default: "md",
		validator: (v) => [
			"xs",
			"sm",
			"md",
			"lg",
			"xl"
		].includes(v) || validateNumber(v)
	},
	/**
	* Size token used for month labels.
	*
	* @category style
	*/
	monthLabelSize: {
		type: String,
		default: "sm",
		validator: (v) => [
			"xxs",
			"xs",
			"sm",
			"md",
			"lg",
			"xl",
			"xxl"
		].includes(v) || !!v && v.length > 0
	}
};
function useMonth(props, emit, { times, parsedStart, parsedEnd, size, headerColumnRef }) {
	const parsedMinWeeks = computed(() => parseInt(props.minWeeks, 10));
	const parsedMinDays = computed(() => parsedMinWeeks.value * props.weekdays.length);
	const calendarToday = computed(() => toCalendarTimestamp(times.today, props.calendarSystem));
	const parsedMonthStart = computed(() => {
		const calendarStart = getCalendarStartOfMonth(parsedStart.value, props.calendarSystem);
		return getCalendarStartOfWeek(calendarStart, props.weekdays, props.calendarSystem, calendarToday.value);
	});
	const parsedMonthEnd = computed(() => {
		const calendarEnd = getCalendarEndOfMonth(parsedEnd.value, props.calendarSystem);
		return getCalendarEndOfWeek(calendarEnd, props.weekdays, props.calendarSystem, calendarToday.value);
	});
	const parsedCellWidth = computed(() => {
		let width = 0;
		if (props.cellWidth) width = resolveCssLength(props.cellWidth, headerColumnRef.value);
		else if (size.width > 0 && headerColumnRef.value) width = headerColumnRef.value.offsetWidth / props.weekdays.length;
		return width;
	});
	/**
	* Returns the days of the specified month
	*/
	const days = computed(() => createCalendarDayList(parsedMonthStart.value, parsedMonthEnd.value, calendarToday.value, props.calendarSystem, {
		weekdays: props.weekdays,
		disabledBefore: props.disabledBefore,
		disabledAfter: props.disabledAfter,
		disabledWeekdays: props.disabledWeekdays,
		disabledDays: props.disabledDays,
		max: Number.MAX_SAFE_INTEGER,
		min: parsedMinDays.value
	}));
	/**
	* Returns the first week of the month for calculating the weekday headers
	*/
	const todayWeek = computed(() => {
		const day = calendarToday.value;
		const start = getCalendarStartOfWeek(day, props.weekdays, props.calendarSystem, day);
		const end = getCalendarEndOfWeek(day, props.weekdays, props.calendarSystem, day);
		return createCalendarDayList(start, end, day, props.calendarSystem, {
			weekdays: props.weekdays,
			disabledBefore: props.disabledBefore,
			disabledAfter: props.disabledAfter,
			disabledWeekdays: props.disabledWeekdays,
			disabledDays: props.disabledDays,
			max: props.weekdays.length,
			min: props.weekdays.length
		});
	});
	/**
	* Returns a function that formats the month name using the locale
	*/
	const monthFormatter = computed(() => {
		const formatter = getCalendarMonthFormatter(props.calendarSystem);
		return (timestamp, short) => formatter(timestamp.month, short === true ? "short" : "long", props.locale, timestamp.year);
	});
	const parsedBreakpoint = computed(() => {
		switch (props.breakpoint) {
			case "xs": return 300;
			case "sm": return 350;
			case "md": return 400;
			case "lg": return 450;
			case "xl": return 500;
			default: return parseInt(props.breakpoint, 10);
		}
	});
	const parsedMonthLabelSize = computed(() => {
		switch (props.monthLabelSize) {
			case "xxs": return ".4em";
			case "xs": return ".6em";
			case "sm": return ".8em";
			case "md": return "1.0em";
			case "lg": return "1.2em";
			case "xl": return "1.4em";
			case "xxl": return "1.6em";
			default: return props.monthLabelSize;
		}
	});
	let firstTime = true;
	const isMiniMode = computed(() => {
		const val = props.miniMode === true || props.miniMode === "auto" && props.breakpoint !== void 0 && size.width < parsedBreakpoint.value;
		if (firstTime) {
			firstTime = false;
			emit("mini-mode", val);
		}
		return val;
	});
	watch(isMiniMode, (val) => {
		emit("mini-mode", val);
	});
	/**
	* Checks if the given day is outside the current month's range.
	*
	* @param day - The day to check.
	* @returns `true` if the day is outside the current month's range, `false` otherwise.
	*/
	function isOutside(day) {
		return isOutsideCalendarMonth(day, parsedStart.value, props.calendarSystem);
	}
	return {
		parsedCellWidth,
		parsedMinWeeks,
		parsedMinDays,
		parsedMonthStart,
		parsedMonthEnd,
		parsedBreakpoint,
		parsedMonthLabelSize,
		days,
		todayWeek,
		isMiniMode,
		monthFormatter,
		isOutside
	};
}

//#endregion
export { useMonth as default, useMonthProps };