import { computed, getCurrentInstance } from "vue";

//#region src/composables/useEmitListeners.ts
/**
* Regular expression to match event listeners starting with 'on'.
*/
const listenerRE = /^on[A-Z]/;
/**
* Provides computed event listeners from the component instance.
* @param {ComponentInternalInstance | null} vm - Vue's component instance (defaults to `getCurrentInstance()`).
* @returns {{ emitListeners: EmitListeners }} - Computed map of event listeners.
*/
function useEmitListeners(vm = getCurrentInstance()) {
	return { emitListeners: computed(() => {
		const listeners = {};
		if (vm?.vnode?.props) Object.keys(vm.vnode.props).forEach((key) => {
			if (listenerRE.test(key)) listeners[key] = true;
		});
		return listeners;
	}) };
}

//#endregion
export { useEmitListeners as default };