import ResizeObserverDirective from "../directives/ResizeObserver.js";
import { computed, h, reactive, ref, withDirectives } from "vue";

//#region src/composables/useCalendar.ts
/**
* The main QCalendar wrapper
* All others are a child to this one
*/
function useCalendar(props, renderFunc, { scrollArea, pane, keyboardActive }) {
	if (!renderFunc) {
		const msg = "[error: renderCalendar] no renderFunc has been supplied to useCalendar";
		console.error(msg);
		throw new Error(msg);
	}
	const size = reactive({
		width: 0,
		height: 0
	}), rootRef = ref(null);
	function __onResize({ width, height }) {
		size.width = width;
		size.height = height;
	}
	const scrollWidth = computed(() => {
		return props.noScroll !== true ? scrollArea.value && pane.value && size.height ? scrollArea.value.offsetWidth - pane.value.offsetWidth : 0 : 0;
	});
	function __initCalendar() {}
	function __renderCalendar() {
		const data = {
			ref: rootRef,
			role: "complementary",
			lang: props.locale,
			dir: props.dir,
			class: {
				"q-calendar": true,
				"q-calendar--dark": props.dark === true,
				"q-calendar__bordered": props.bordered === true,
				"q-calendar--keyboard-active": keyboardActive?.value === true
			}
		};
		return withDirectives(h("div", { ...data }, [renderFunc()]), [[ResizeObserverDirective, __onResize]]);
	}
	return {
		rootRef,
		scrollWidth,
		__initCalendar,
		__renderCalendar
	};
}

//#endregion
export { useCalendar as default };