import { h } from "vue";

//#region src/composables/useFocusHelper.ts
/**
* Creates an accessible focus helper span element.
* @returns {VNode[]} An array containing a single span VNode.
*/
function useFocusHelper() {
	return [h("span", {
		"aria-hidden": "true",
		class: "q-calendar__focus-helper"
	})];
}

//#endregion
export { useFocusHelper as default };