import { convertToUnit } from "../utils/helpers.js";
import { computed } from "vue";

//#region src/composables/useCellWidth.ts
const useCellWidthProps = { 
/**
* Fixed cell width used by sticky or horizontally scrolling displays.
*
* @category layout
*/
cellWidth: [Number, String] };
function useCellWidth(props) {
	return {
		isSticky: computed(() => props.cellWidth !== void 0),
		cellWidthStyle: computed(() => convertToUnit(props.cellWidth))
	};
}

//#endregion
export { useCellWidth as default, useCellWidthProps };