import { isGregorianCalendar, toCalendarTimestamp } from "../utils/calendarSystem.js";
import { computed } from "vue";
import { copyTimestamp, daysInMonth, getCalendarEndOfMonth, getCalendarStartOfMonth, getEndOfMonth, getEndOfWeek, getStartOfMonth, getStartOfWeek, gregorianCalendar, moveRelativeDays, nextDay, updateFormatted } from "@timestamp-js/core";

//#region src/composables/useRenderValues.ts
function useRenderValues(props, { parsedView, parsedValue, times }) {
	const calendarToday = computed(() => toCalendarTimestamp(times.today, props.calendarSystem));
	function getMonthRange(around) {
		const calendar = props.calendarSystem ?? gregorianCalendar;
		if (isGregorianCalendar(calendar) === true) {
			const start = getStartOfMonth(around);
			return {
				start,
				end: getEndOfMonth(around),
				maxDays: daysInMonth(start.year, start.month)
			};
		}
		const calendarAround = toCalendarTimestamp(around, calendar);
		const calendarStart = getCalendarStartOfMonth(calendarAround, calendar);
		return {
			start: calendarStart,
			end: getCalendarEndOfMonth(calendarAround, calendar),
			maxDays: calendar.daysInMonth(calendarStart.year, calendarStart.month)
		};
	}
	return { renderValues: computed(() => {
		const around = parsedValue.value;
		let maxDays = props.maxDays ?? 1;
		let start = around;
		let end = around;
		switch (parsedView.value) {
			case "month": {
				const monthRange = getMonthRange(around);
				start = monthRange.start;
				end = monthRange.end;
				maxDays = monthRange.maxDays;
				break;
			}
			case "week":
			case "week-agenda":
			case "week-scheduler":
				start = getStartOfWeek(around, props.weekdays, calendarToday.value, props.calendarSystem);
				end = getEndOfWeek(start, props.weekdays, calendarToday.value, props.calendarSystem);
				maxDays = props.weekdays.length;
				break;
			case "day":
			case "scheduler":
			case "agenda":
				end = moveRelativeDays(copyTimestamp(end), nextDay, maxDays > 1 ? maxDays - 1 : maxDays, props.weekdays, props.calendarSystem);
				end = updateFormatted(end, props.calendarSystem);
				break;
			case "month-interval":
			case "month-scheduler":
			case "month-agenda": {
				const monthRange = getMonthRange(around);
				start = monthRange.start;
				end = monthRange.end;
				end = updateFormatted(end, props.calendarSystem);
				maxDays = monthRange.maxDays;
				break;
			}
			case "resource":
				maxDays = 1;
				end = moveRelativeDays(copyTimestamp(end), nextDay, maxDays, props.weekdays, props.calendarSystem);
				end = updateFormatted(end, props.calendarSystem);
		}
		return {
			start,
			end,
			maxDays
		};
	}) };
}

//#endregion
export { useRenderValues as default };