//#region src/utils/aria.ts
const ariaHiddenAttrs = { "aria-hidden": "true" };
const presentationRoleAttrs = { role: "presentation" };
function getAriaLabelAttrs(label) {
	return { "aria-label": label };
}
function setAriaLabel(attrs, label, enabled) {
	if (enabled === true) Object.assign(attrs, getAriaLabelAttrs(label));
}

//#endregion
export { ariaHiddenAttrs, getAriaLabelAttrs, presentationRoleAttrs, setAriaLabel };